                  <AvatarFallback>{owner.slice(0, 1)}</AvatarFallback>
                </Avatar>
                <span>{owner}</span>
              </span>
            ))}
          </div>
        </DetailRow>
        <DetailRow
          label="재시도 정책"
          icon={<HugeiconsIcon icon={Refresh01Icon} strokeWidth={2} className="size-3.5" />}
        >
          {SESSION.retryPolicy}
        </DetailRow>
        <DetailRow
          label="최대 재시도"
          icon={<HugeiconsIcon icon={HashIcon} strokeWidth={2} className="size-3.5" />}
        >
          {SESSION.maxRetries}
        </DetailRow>
        <DetailRow
          label="실패 시"
          icon={<HugeiconsIcon icon={BellIcon} strokeWidth={2} className="size-3.5" />}
        >
          {SESSION.onFailure}
        </DetailRow>
        <DetailRow
