          <ProvenanceRowMeta>결제 프로세서 응답 · payments.refunds.create</ProvenanceRowMeta>
          <ProvenanceRowStatus verified>확인됨</ProvenanceRowStatus>
        </ProvenanceRow>
        <ProvenanceRow source="human" verified>
          <ProvenanceRowLabel source="human" />
          <ProvenanceRowMeta>
            소유자 {SESSION.owners.join(", ")} · 읽기 전용 모니터링
          </ProvenanceRowMeta>
          <ProvenanceRowStatus verified>확인됨</ProvenanceRowStatus>
        </ProvenanceRow>
      </ProvenanceList>
    </ProvenancePanel>
